static int checks=0;static bool require(bool ok,const char* message){++checks;if(!ok)std::cerr<<"FAIL: "<<message<<"\n";return ok;}
#define CHECK(test,message) if(!require((test),message))return 1
static void dry(Processor& p){p.set("duckOn",0);p.set("gateOn",0);p.set("panOn",0);p.set("output",0);p.set("mix",1);p.set("mode",3);}
static AudioBuffer<float> input(int channels,int n){AudioBuffer<float> b(channels,n);for(int c=0;c<channels;++c)for(int i=0;i<n;++i)b.setSample(c,i,.35f*std::sin(i*.027f+c*.3f));return b;}
static double energy(AudioBuffer<float>& b){double e=0;for(int c=0;c<b.getNumChannels();++c)for(int i=0;i<b.getNumSamples();++i)e+=b.getSample(c,i)*b.getSample(c,i);return e;}
